<?php

namespace Tests\Feature;

use Tests\TestCase;
use App\Models\User;
use App\Models\FinanceBillingType;
use App\Models\FinanceSppRule;
use Illuminate\Foundation\Testing\DatabaseMigrations;
use Illuminate\Support\Facades\DB;

/**
 * Tests for Finance Admin Configuration Foundation.
 *
 * Covers:
 *  - Admin authorization (role:admin required)
 *  - Billing type CRUD + toggle
 *  - SPP rule CRUD + toggle
 *  - Validation (amount, code format, duplicate code, duplicate rule scope)
 *  - Audit log created on every mutation
 *  - No billing generated by any action
 *  - Existing student/bill data untouched
 */
class FinanceSettingTest extends TestCase
{
    use DatabaseMigrations;

    // ================================================================
    // HELPERS
    // ================================================================

    private function makeAdmin(): User
    {
        return User::create([
            'name'     => 'Admin TU',
            'username' => 'admin001',
            'email'    => 'admin@tu.test',
            'password' => bcrypt('password'),
            'role'     => 'admin',
        ]);
    }

    private function makeTuStaff(): User
    {
        return User::create([
            'name'     => 'Staff TU',
            'username' => 'staff001',
            'email'    => 'staff@tu.test',
            'password' => bcrypt('password'),
            'role'     => 'tu',
        ]);
    }

    private function makeBillingType(array $overrides = []): FinanceBillingType
    {
        return FinanceBillingType::create(array_merge([
            'code'         => 'SPP',
            'name'         => 'SPP Bulanan',
            'is_recurring' => true,
            'sort_order'   => 1,
            'is_active'    => true,
        ], $overrides));
    }

    private function makeSppRule(array $overrides = []): FinanceSppRule
    {
        // Ensure billing type exists
        if (!FinanceBillingType::where('code', 'SPP')->exists()) {
            $this->makeBillingType();
        }

        return FinanceSppRule::create(array_merge([
            'name'              => 'SPP TA 2026/2027',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => 7,
            'start_year'        => 2026,
            'amount'            => 500000,
            'due_day'           => 10,
            'is_active'         => true,
        ], $overrides));
    }

    // ================================================================
    // AUTHORIZATION
    // ================================================================

    public function test_non_admin_cannot_access_finance_settings(): void
    {
        $staff = $this->makeTuStaff();

        $this->actingAs($staff)
             ->get('/finance/settings')
             ->assertStatus(403);
    }

    public function test_guest_redirected_from_finance_settings(): void
    {
        $this->get('/finance/settings')->assertRedirect('/login');
    }

    public function test_admin_can_access_finance_settings(): void
    {
        $admin = $this->makeAdmin();

        $this->actingAs($admin)
             ->get('/finance/settings')
             ->assertStatus(200)
             ->assertSee('Konfigurasi Finance');
    }

    // ================================================================
    // BILLING TYPE — CREATE
    // ================================================================

    public function test_admin_can_create_billing_type(): void
    {
        $admin = $this->makeAdmin();

        $response = $this->actingAs($admin)->post('/finance/settings/billing-types', [
            'code'         => 'GEDUNG',
            'name'         => 'Biaya Gedung',
            'description'  => 'Biaya pembangunan',
            'is_recurring' => '0',
            'sort_order'   => '2',
        ]);

        $response->assertRedirect('/finance/settings');
        $this->assertDatabaseHas('finance_billing_types', [
            'code'    => 'GEDUNG',
            'name'    => 'Biaya Gedung',
            'is_active' => true,
        ]);
    }

    public function test_billing_type_code_must_be_uppercase_alphanumeric(): void
    {
        $admin = $this->makeAdmin();

        $this->actingAs($admin)->post('/finance/settings/billing-types', [
            'code' => 'spp-invalid!',
            'name' => 'Test',
        ])->assertSessionHasErrors('code');

        $this->assertDatabaseMissing('finance_billing_types', ['code' => 'spp-invalid!']);
    }

    public function test_billing_type_code_must_be_unique(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP']);

        $this->actingAs($admin)->post('/finance/settings/billing-types', [
            'code' => 'SPP',
            'name' => 'Duplicate SPP',
        ])->assertSessionHasErrors('code');

        $this->assertEquals(1, FinanceBillingType::where('code', 'SPP')->count());
    }

    // ================================================================
    // BILLING TYPE — UPDATE
    // ================================================================

    public function test_admin_can_update_billing_type(): void
    {
        $admin = $this->makeAdmin();
        $bt    = $this->makeBillingType();

        $this->actingAs($admin)->put("/finance/settings/billing-types/{$bt->id}", [
            'name'         => 'SPP Bulanan Updated',
            'is_recurring' => '1',
            'sort_order'   => '5',
        ])->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_billing_types', [
            'id'   => $bt->id,
            'name' => 'SPP Bulanan Updated',
        ]);
    }

    // ================================================================
    // BILLING TYPE — TOGGLE
    // ================================================================

    public function test_admin_can_deactivate_billing_type(): void
    {
        $admin = $this->makeAdmin();
        $bt    = $this->makeBillingType(['is_active' => true]);

        $this->actingAs($admin)
             ->post("/finance/settings/billing-types/{$bt->id}/toggle")
             ->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_billing_types', [
            'id'        => $bt->id,
            'is_active' => false,
        ]);
    }

    public function test_admin_can_reactivate_billing_type(): void
    {
        $admin = $this->makeAdmin();
        $bt    = $this->makeBillingType(['is_active' => false]);

        $this->actingAs($admin)
             ->post("/finance/settings/billing-types/{$bt->id}/toggle")
             ->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_billing_types', [
            'id'        => $bt->id,
            'is_active' => true,
        ]);
    }

    // ================================================================
    // SPP RULE — CREATE
    // ================================================================

    public function test_admin_can_create_spp_rule(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);

        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'SPP TA 2026/2027',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '500000',
            'due_day'           => '10',
        ])->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_spp_rules', [
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'amount'            => '500000.00',
        ]);
    }

    public function test_spp_rule_amount_must_be_at_least_1000(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);

        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'Test',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '500',  // terlalu kecil
            'due_day'           => '10',
        ])->assertSessionHasErrors('amount');

        $this->assertEquals(0, FinanceSppRule::count());
    }

    public function test_spp_rule_due_day_max_28(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);

        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'Test',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '500000',
            'due_day'           => '31',  // invalid
        ])->assertSessionHasErrors('due_day');
    }

    public function test_spp_rule_academic_year_format_validated(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);

        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'Test',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026-2027',  // format salah
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '500000',
            'due_day'           => '10',
        ])->assertSessionHasErrors('academic_year');
    }

    public function test_duplicate_spp_rule_scope_rejected(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);
        $this->makeSppRule(); // tahun 2026/2027, SPP, no class scope

        // Coba buat rule dengan kombinasi yang sama
        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'Duplicate Rule',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '600000',
            'due_day'           => '10',
        ])->assertSessionHasErrors('billing_type_code');

        $this->assertEquals(1, FinanceSppRule::count());
    }

    // ================================================================
    // SPP RULE — UPDATE
    // ================================================================

    public function test_admin_can_update_spp_rule(): void
    {
        $admin = $this->makeAdmin();
        $rule  = $this->makeSppRule();

        $this->actingAs($admin)->put("/finance/settings/spp-rules/{$rule->id}", [
            'name'        => 'SPP Updated',
            'amount'      => '600000',
            'due_day'     => '15',
            'start_month' => '7',
            'start_year'  => '2026',
        ])->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_spp_rules', [
            'id'     => $rule->id,
            'name'   => 'SPP Updated',
            'amount' => '600000.00',
        ]);
    }

    // ================================================================
    // SPP RULE — TOGGLE
    // ================================================================

    public function test_admin_can_toggle_spp_rule(): void
    {
        $admin = $this->makeAdmin();
        $rule  = $this->makeSppRule(['is_active' => true]);

        $this->actingAs($admin)
             ->post("/finance/settings/spp-rules/{$rule->id}/toggle")
             ->assertRedirect('/finance/settings');

        $this->assertDatabaseHas('finance_spp_rules', [
            'id'        => $rule->id,
            'is_active' => false,
        ]);
    }

    // ================================================================
    // AUDIT LOG
    // ================================================================

    public function test_audit_log_created_on_billing_type_create(): void
    {
        $admin = $this->makeAdmin();

        $this->actingAs($admin)->post('/finance/settings/billing-types', [
            'code'         => 'AUDIT_TEST',
            'name'         => 'Audit Test Type',
            'is_recurring' => '0',
            'sort_order'   => '99',
        ]);

        $this->assertDatabaseHas('audit_logs', [
            'user_id'     => $admin->id,
            'action'      => 'CREATE',
            'module'      => 'FINANCE_CONFIG',
            'target_type' => 'FinanceBillingType',
        ]);
    }

    public function test_audit_log_created_on_spp_rule_update(): void
    {
        $admin = $this->makeAdmin();
        $rule  = $this->makeSppRule();

        $this->actingAs($admin)->put("/finance/settings/spp-rules/{$rule->id}", [
            'name'        => 'Updated For Audit',
            'amount'      => '750000',
            'due_day'     => '10',
            'start_month' => '7',
            'start_year'  => '2026',
        ]);

        $this->assertDatabaseHas('audit_logs', [
            'user_id'     => $admin->id,
            'action'      => 'UPDATE',
            'module'      => 'FINANCE_CONFIG',
            'target_type' => 'FinanceSppRule',
            'target_id'   => $rule->id,
        ]);
    }

    // ================================================================
    // NO BILLING GENERATED
    // ================================================================

    public function test_no_student_bills_generated_by_config_actions(): void
    {
        $admin = $this->makeAdmin();
        $this->makeBillingType(['code' => 'SPP', 'is_active' => true]);

        // Create billing type
        $this->actingAs($admin)->post('/finance/settings/billing-types', [
            'code'         => 'GEDUNG',
            'name'         => 'Test',
            'is_recurring' => '0',
            'sort_order'   => '1',
        ]);

        // Create SPP rule
        $this->actingAs($admin)->post('/finance/settings/spp-rules', [
            'name'              => 'Test Rule',
            'billing_type_code' => 'SPP',
            'academic_year'     => '2026/2027',
            'start_month'       => '7',
            'start_year'        => '2026',
            'amount'            => '500000',
            'due_day'           => '10',
        ]);

        // TIDAK ada student_bills yang dibuat
        $this->assertEquals(0, \App\Models\StudentBill::count());
    }

    // ================================================================
    // NON-ADMIN CANNOT MUTATE
    // ================================================================

    public function test_non_admin_cannot_create_billing_type(): void
    {
        $staff = $this->makeTuStaff();

        $this->actingAs($staff)->post('/finance/settings/billing-types', [
            'code' => 'HACKED',
            'name' => 'Hacked Type',
        ])->assertStatus(403);

        $this->assertDatabaseMissing('finance_billing_types', ['code' => 'HACKED']);
    }

    public function test_non_admin_cannot_create_spp_rule(): void
    {
        $staff = $this->makeTuStaff();

        $this->actingAs($staff)->post('/finance/settings/spp-rules', [
            'name'   => 'Hacked Rule',
            'amount' => '999999',
        ])->assertStatus(403);

        $this->assertEquals(0, FinanceSppRule::count());
    }
}
